  upcoming(n = 5) { const now = Date.now() - DAY; return this.profile.trips.filter(t => !t.date || new Date(t.date).getTime() >= now).sort((a, b) => new Date(a.date || 0) - new Date(b.date || 0)).slice(0, n); }
